const obligationPayees = `-- name: ObligationPayees :many
SELECT id FROM organization_memberships m
WHERE m.organization_id = $1
  AND (m.lifecycle_state = 'active'
       -- "life members exempt per org rule": they join the payee set only
       -- when the schedule opts in (applies_to.include_life_members).
       OR (m.lifecycle_state = 'life_member' AND $2::bool))
  AND (COALESCE($3::text[], '{}'::text[]) = '{}'::text[]
       OR m.category = ANY($3::text[]))
  AND (COALESCE($4::uuid[], '{}'::uuid[]) = '{}'::uuid[]
       OR m.org_unit_id = ANY($4::uuid[]))
`

