const registrationSchedules = `-- name: RegistrationSchedules :many
SELECT s.id, s.organization_id, s.contribution_type_id, s.name, s.amount_minor, s.currency, s.recurrence, s.applies_to, s.starts_on, s.ends_on, s.active FROM dues_schedules s
JOIN contribution_types ct ON ct.id = s.contribution_type_id
WHERE s.organization_id = $1 AND s.active AND ct.key = 'registration'
`

// 'registration' contribution types back the ADR-014 approved→registered
// guard: an org that charges registration publishes a schedule for it.
func (q *Queries) RegistrationSchedules(ctx context.Context, organizationID pgtype.UUID) ([]DuesSchedules, error) {
	rows, err := q.db.Query(ctx, registrationSchedules, organizationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DuesSchedules
	for rows.Next() {
		var i DuesSchedules
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.ContributionTypeID,
			&i.Name,
			&i.AmountMinor,
			&i.Currency,
			&i.Recurrence,
			&i.AppliesTo,
			&i.StartsOn,
			&i.EndsOn,
			&i.Active,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

