const updateDuesSchedule = `-- name: UpdateDuesSchedule :execrows
UPDATE dues_schedules SET
  name = COALESCE($1::text, name),
  amount_minor = COALESCE($2::bigint, amount_minor),
  recurrence = COALESCE($3::text, recurrence),
  applies_to = COALESCE($4::jsonb, applies_to),
  starts_on = COALESCE($5::date, starts_on),
  ends_on = CASE WHEN $6::boolean THEN NULL
                 ELSE COALESCE($7::date, ends_on) END,
  active = COALESCE($8::boolean, active)
WHERE id = $9::uuid AND organization_id = $10::uuid
`

type UpdateDuesScheduleParams struct {
	Name           pgtype.Text `json:"name"`
	AmountMinor    pgtype.Int8 `json:"amount_minor"`
	Recurrence     pgtype.Text `json:"recurrence"`
	AppliesTo      []byte      `json:"applies_to"`
	StartsOn       pgtype.Date `json:"starts_on"`
	ClearEndsOn    bool        `json:"clear_ends_on"`
	EndsOn         pgtype.Date `json:"ends_on"`
	Active         pgtype.Bool `json:"active"`
	ID             pgtype.UUID `json:"id"`
	OrganizationID pgtype.UUID `json:"organization_id"`
}

// Full edit surface (catalog PATCH): NULL args keep the column; explicit
// clear_ends_on writes NULL (the "ends_on": null PATCH semantic).
func (q *Queries) UpdateDuesSchedule(ctx context.Context, arg UpdateDuesScheduleParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateDuesSchedule,
		arg.Name,
		arg.AmountMinor,
		arg.Recurrence,
		arg.AppliesTo,
		arg.StartsOn,
		arg.ClearEndsOn,
		arg.EndsOn,
		arg.Active,
		arg.ID,
		arg.OrganizationID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

